import { useState, useContext } from "react";
import { ComplaintContext } from "../context/ComplaintContext";
import "../styles/global.css";

function Dashboard() {
  const { complaints } = useContext(ComplaintContext);
  const [preview, setPreview] = useState(null);

  const departments = [
    { name: "Public Works", icon: "🏗️", sub: ["Road damage","Street light","Garbage"] },
    { name: "Water & Sanitation", icon: "💧", sub: ["Water leakage","Drainage","Sewage"] },
    { name: "Health & Safety", icon: "🏥", sub: ["Hospital issue","Mosquito","Emergency"] },
  ];

  const getCount = (dept) =>
    complaints.filter((c) => c.department === dept).length;

  const ripple = (e) => {
    const card = e.currentTarget;
    const circle = document.createElement("span");
    circle.className = "ripple";

    const rect = card.getBoundingClientRect();
    circle.style.left = `${e.clientX - rect.left}px`;
    circle.style.top = `${e.clientY - rect.top}px`;

    card.appendChild(circle);
    setTimeout(() => circle.remove(), 600);
  };

  return (
    <>
      {/* ⭐ HEADER */}
      <div className="citizen-header">
        <h2>Citizen Dashboard</h2>
        <p>Choose department & file complaint</p>
      </div>

      {/* ⭐ GRID */}
      <div className="dept-grid">
        {departments.map((d) => (
          <div
            key={d.name}
            className="dept-card"
            onClick={(e) => {
              ripple(e);
              setPreview(d);
            }}
          >
            <div className="badge">{getCount(d.name)}</div>

            <div className="icon">{d.icon}</div>
            <h3>{d.name}</h3>
            <p>Click to file complaint</p>
          </div>
        ))}
      </div>

      {/* ⭐ PREVIEW MODAL */}
      {preview && (
        <div className="modal">
          <div className="modal-card">
            <h3>{preview.name}</h3>
            <p>Select category:</p>

            {preview.sub.map((s) => (
              <div key={s} className="sub">{s}</div>
            ))}

            <button onClick={() => setPreview(null)}>Close</button>
          </div>
        </div>
      )}
    </>
  );
}

export default Dashboard;
